def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merge overlapping or touching intervals. Touching means next_start <= previous_end."""
    if not intervals:
        return []

    # Validate intervals
    for interval in intervals:
        if not isinstance(interval, tuple) or len(interval) != 2:
            raise ValueError("Each interval must be a tuple of two integers")
        start, end = interval
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("Interval endpoints must be integers")
        if start > end:
            raise ValueError(f"Invalid interval: start ({start}) > end ({end})")

    # Sort by start, then by end
    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    # Merge
    merged: list[tuple[int, int]] = [sorted_intervals[0]]
    for start, end in sorted_intervals[1:]:
        prev_start, prev_end = merged[-1]
        if start <= prev_end:
            # Overlapping or touching
            merged[-1] = (prev_start, max(prev_end, end))
        else:
            merged.append((start, end))

    return merged

